/* o'zbek lotin → kirill */
function cyr(s){
  if(!s) return s;
  const AP="['‘’ʻʼ`]";
  return String(s).split(/(<[^>]*>|\{[a-z_]+\})/).map((part,i)=>{
    if(i%2) return part;
    let t=part
      .replace(new RegExp("O"+AP,"g"),"Ў").replace(new RegExp("o"+AP,"g"),"ў").replace(new RegExp("G"+AP,"g"),"Ғ").replace(new RegExp("g"+AP,"g"),"ғ")
      .replace(/SH/g,"Ш").replace(/Sh/g,"Ш").replace(/sh/g,"ш").replace(/CH/g,"Ч").replace(/Ch/g,"Ч").replace(/ch/g,"ч")
      .replace(/Yo/g,"Ё").replace(/yo/g,"ё").replace(/Yu/g,"Ю").replace(/yu/g,"ю").replace(/Ya/g,"Я").replace(/ya/g,"я").replace(/Ye/g,"Е").replace(/ye/g,"е")
      .replace(/ts/g,"ц")
      .replace(/(^|[^A-Za-zА-Яа-яЎўҒғЁё])E/g,"$1Э").replace(/(^|[^A-Za-zА-Яа-яЎўҒғЁё])e/g,"$1э")
      .replace(new RegExp(AP,"g"),"ъ");
    const M={A:"А",B:"Б",D:"Д",E:"Е",F:"Ф",G:"Г",H:"Ҳ",I:"И",J:"Ж",K:"К",L:"Л",M:"М",N:"Н",O:"О",P:"П",Q:"Қ",R:"Р",S:"С",T:"Т",U:"У",V:"В",X:"Х",Y:"Й",Z:"З",C:"С",W:"В",
      a:"а",b:"б",d:"д",e:"е",f:"ф",g:"г",h:"ҳ",i:"и",j:"ж",k:"к",l:"л",m:"м",n:"н",o:"о",p:"п",q:"қ",r:"р",s:"с",t:"т",u:"у",v:"в",x:"х",y:"й",z:"з",c:"с",w:"в"};
    return t.replace(/[A-Za-z]/g,c=>M[c]||c);
  }).join("");
}
const D = ()=>I18N[LANG==="uzk"?"uz":LANG]||I18N.uz;
function t(k,v){ let s=D()[k]; if(s==null) s=I18N.en[k]; if(s==null) s=I18N.uz[k]??k; if(LANG==="uzk"&&typeof s==="string") s=cyr(s);
  if(v) for(const x in v) s=s.split("{"+x+"}").join(v[x]); return s; }
const deepCyr=o=>typeof o==="string"?cyr(o):Array.isArray(o)?o.map(deepCyr):o&&typeof o==="object"?Object.fromEntries(Object.entries(o).map(([k,v])=>[k,deepCyr(v)])):o;
function tl(k){ let o=D()[k]??I18N.en[k]; if(LANG==="uzk") o=deepCyr(o); return o; }
const CAT=()=>tl("cat"), REGN=()=>tl("reg"), PER=()=>tl("per");
